public void read(org.apache.thrift.protocol.TProtocol iprot, modifyNodeManagerConfig_args struct) throws org.apache.thrift.TException {
        org.apache.thrift.protocol.TField schemeField;
        iprot.readStructBegin();
        while (true)
        {
          schemeField = iprot.readFieldBegin();
          if (schemeField.type == org.apache.thrift.protocol.TType.STOP) { 
            break;
          }
          switch (schemeField.id) {
            case 1: if (schemeField.type == org.apache.thrift.protocol.TType.STRING) {
                struct.nodeId = iprot.readString();
                struct.setNodeIdIsSet(true);
              } else { 
                org.apache.thrift.protocol.TProtocolUtil.skip(iprot, schemeField.type);
              }
              break;
            case 2: if (schemeField.type == org.apache.thrift.protocol.TType.STRING) {
                struct.propertyName = iprot.readString();
                struct.setPropertyNameIsSet(true);
              } else { 
                org.apache.thrift.protocol.TProtocolUtil.skip(iprot, schemeField.type);
              }
              break;
            case 3: if (schemeField.type == org.apache.thrift.protocol.TType.STRING) {
                struct.propertyValue = iprot.readString();
                struct.setPropertyValueIsSet(true);
              } else { 
                org.apache.thrift.protocol.TProtocolUtil.skip(iprot, schemeField.type);
              }
              break;
            default:
              org.apache.thrift.protocol.TProtocolUtil.skip(iprot, schemeField.type);
          }
          iprot.readFieldEnd();
        }
        iprot.readStructEnd();
        struct.validate();
      }

@Override
    public void onCompletion(MediaPlayer mp) {
        DebugLog.v(TAG, "onCompletion");
        try {
            if (mPlayIndex != null && mSegmentPlayer != null) {
                int count = mPlayIndex.mSegmentList.size();
                int nextOrder = mSegmentPlayer.getOrder() + 1;
                if (nextOrder < count) {
                    mSegmentPlayer.release();
                    mIsMediaSwitchEnd = false;
                    if (mOnInfoListener != null) {
                        mOnInfoListener.onInfo(this,
                                MediaPlayer.MEDIA_INFO_BUFFERING_START, 0);
                    }
                    Segment nextSegment = mPlayIndex.mSegmentList
                            .get(nextOrder);
                    if (nextSegment != null) {
                        mSegmentPlayer = createItemPlayer();
                        int startTime = mPlayIndex.getStartTime(nextOrder);
                        mSegmentPlayer.setSegment(nextOrder, startTime,
                                nextSegment);
                        mSegmentPlayer.prepareAsync();
                    }
                    return;
                }
            }
            if (mOnCompletionListener != null) {
                mOnCompletionListener.onCompletion(this);
            }
            return;
        } catch (IllegalArgumentException e) {
            e.printStackTrace();
        } catch (IllegalStateException e) {
            e.printStackTrace();
        } catch (IOException e) {
            e.printStackTrace();
        }
        if (mOnErrorListener != null) {
            mOnErrorListener.onError(this, 1, 1);
        }
    }

