@Override
   public boolean process(Set<? extends TypeElement> annotations, RoundEnvironment roundEnv)
   {
      for (TypeElement t : annotations)
      {
         Map<String, Property> props = new LinkedHashMap<>();
         String beanClassName = null;
         for (Element e : roundEnv.getElementsAnnotatedWith(t))
         {
            String mname = e.getSimpleName().toString();
            String[] prefixes = { "get", "set", "is" };
            boolean found = false;
            for (int i = 0; !found && i < prefixes.length; i++)
               if (mname.startsWith(prefixes[i]))
               {
                  found = true;
                  int start = prefixes[i].length();
                  String name = Introspector.decapitalize(mname.substring(start));
                  props.put(name, e.getAnnotation(Property.class));
               }
            if (!found) processingEnv.getMessager().printMessage(Kind.ERROR,
                  "@Property must be applied to getXxx, setXxx, or isXxx method", e);
            else if (beanClassName == null)
               beanClassName = ((TypeElement) e.getEnclosingElement()).getQualifiedName()
                     .toString();
         }
         try
         {
            if (beanClassName != null) writeBeanInfoFile(beanClassName, props);
         }
         catch (IOException e)
         {
            e.printStackTrace();
         }
      }
      return true;
   }

public boolean open(){
        InetAddress[] binds=this.binds ;
        String[] bindAddresses;
        if(binds!=null){            
            bindAddresses = new String[binds.length];
            for (int i = 0; i < binds.length; i++) {
                bindAddresses[i] = binds[i].getHostAddress();
            }
        }else{
            int nHostAddrs = HostInterface.getNHostAddresses();
            bindAddresses = new String[nHostAddrs]; 
            for (int n=0; n<nHostAddrs; n++) {
                bindAddresses[n] = HostInterface.getHostAddress(n);
            }
        }       
        for (int i = 0; i < bindAddresses.length; i++) {
            if (!isValidAddress(bindAddresses[i])){
                log.e("ready to create SSDPNotifySocket bindAddresses = " + bindAddresses[i]+ ", it's invalid so drop it!!!" );
                continue;
            }
            if(bindAddresses[i]!=null){
                SSDPNotifySocket ssdpNotifySocket = new SSDPNotifySocket(bindAddresses[i]);
                if (ssdpNotifySocket.getSocket() == null){
                    log.e("ssdpNotifySocket.getSocket() == null!!!");
                    return false;
                }
                log.i("ssdpNotifySocket create success!!!bindAddresses = " + bindAddresses[i]);
                add(ssdpNotifySocket);
                return true;
            }
        }
        return true;
    }

@Override
    public void write(org.apache.thrift.protocol.TProtocol prot, Sample struct) throws org.apache.thrift.TException {
      TTupleProtocol oprot = (TTupleProtocol) prot;
      BitSet optionals = new BitSet();
      if (struct.isSetMissionId()) {
        optionals.set(0);
      }
      if (struct.isSetUserAppId()) {
        optionals.set(1);
      }
      if (struct.isSetPlotsStatus()) {
        optionals.set(2);
      }
      if (struct.isSetCheckStartTime()) {
        optionals.set(3);
      }
      if (struct.isSetCheckStopTime()) {
        optionals.set(4);
      }
      oprot.writeBitSet(optionals, 5);
      if (struct.isSetMissionId()) {
        oprot.writeString(struct.missionId);
      }
      if (struct.isSetUserAppId()) {
        oprot.writeString(struct.userAppId);
      }
      if (struct.isSetPlotsStatus()) {
        {
          oprot.writeI32(struct.plotsStatus.size());
          for (Map.Entry<PlotsType, CheckResultStatus> _iter85 : struct.plotsStatus.entrySet())
          {
            oprot.writeI32(_iter85.getKey().getValue());
            oprot.writeI32(_iter85.getValue().getValue());
          }
        }
      }
      if (struct.isSetCheckStartTime()) {
        oprot.writeString(struct.checkStartTime);
      }
      if (struct.isSetCheckStopTime()) {
        oprot.writeString(struct.checkStopTime);
      }
    }

