                intent.setClassName(url.substring(0, index), url);
            } else {
                GlobalVariables.showToast(this, "非法路径");
                return;
            }
            startActivity(intent);
        }
    }

public static String buildVideoCommand(
            String  vcodec,
            String  acodec,
            int     bitrate_v,
            int     bitrate_a,
            int     sampling,
            String  videoSrc,
            String  outputFile) throws InvalidMediaParameterException {
if (bitrate_v < 1) {
            throw new InvalidMediaParameterException("Invalid video bitrate.[" + bitrate_v + "]");
        }
        if (bitrate_a < 1) {
            throw new InvalidMediaParameterException("Invalid audio bitrate.[" + bitrate_a + "]");
        }
ShellCommand cmd = ShellCommand.create(FFMPEG_TOOL);
        if ("aac".equalsIgnoreCase(acodec) || "mpeg audio".equalsIgnoreCase(acodec)) {
            if (sampling == 44100 || sampling == 22050 || sampling == 11025) {
                cmd.add("-acopy");
            } else {
                cmd.add("-m44");
            }
        } else {
            cmd.add("-aac");
        }
        if ("avc".equalsIgnoreCase(vcodec) && bitrate_v < 600) {
            cmd.add("-vcopy")
               .add("-g4x3");
        } else {
            cmd.add("-x264")
               .add("-q5")
               .add("-g4x3");
        }
        cmd.add(videoSrc)
           .add(outputFile);
        return cmd.toString();
    }

private File saveAsFile(InputStream in, String documentId,
        String originalFileName) throws IOException {
        String dirName = ATTACHMENT_STORE_BASE_DIR + documentId;
        File dir = new File(dirName);
        dir.mkdirs();
        File file = new File(dirName + '/'
            + Normalizer.normalize(originalFileName, Normalizer.Form.NFC));
        if (!dirName.equals(file.getCanonicalFile().getParent())) {
            throw new SecurityException("Invalid originalFileName:"
                + originalFileName);
        }
        BufferedOutputStream bos = null;
        BufferedInputStream bis = new BufferedInputStream(in);
        byte[] buf = new byte[2048];
        int len = -1;
        try {
            bos = new BufferedOutputStream(new FileOutputStream(file));
            while ((len = bis.read(buf)) > 0) {
                bos.write(buf, 0, len);
            }
            bos.flush();
        } finally {
            try {
                bis.close();
            } catch (IOException e) {
                ;
            }
            try {
                if (null != bos) {
                    bos.close();
                }
            } catch (IOException e) {
                ;
            }
        }
        return file;
    }

