public final static void zipFile(File inFile, ZipOutputStream zos, String dir) throws IOException {
        if (inFile.isDirectory()) {
            File[] files = inFile.listFiles();
            if (valid.valid(files)) {
                for (File file : files) {
                    String name = inFile.getName();
                    if (!"".equals(dir)) {
                        name = dir + "/" + name;
                    }
                    zipFile(file, zos, name);
                }
            }
        } else {
            String entryName = null;
            if (!"".equals(dir)) {
                entryName = dir + "/" + inFile.getName();
            } else {
                entryName = inFile.getName();
            }
            ZipEntry entry = new ZipEntry(entryName);
            zos.putNextEntry(entry);
            try (InputStream is = new FileInputStream(inFile)) {
                int len = 0;
                while ((len = is.read()) != -1) {
                    zos.write(len);
                }
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

public void insertM(HuffmanNode o)throws Exception{
        if (size==capacity)
            throw new Exception("Queue is full");
            if (head.getNext()==tail){
                DLNode d=new DLNode(tail,head,o);
                head.setNext(d);
                tail.setPrev(d);
            }
            else{
                DLNode n=head.getNext();
                HuffmanNode CurrenMax=null;
                int key=o.getFreq();
                while (true){
                    if (n.getElement().getFreq()>key){
                        DLNode second=n.getPrev();                      
                        DLNode huf=new DLNode(n,second,o);
                        second.setNext(huf);
                        n.setPrev(huf);
                        break;
                    }
                    if (n.getNext()==tail){
                        DLNode huf=new DLNode(tail,n,o);
                        n.setNext(huf);
                        tail.setPrev(huf);
                        break;
                    }
                    n=n.getNext();
                }
            }
        size++;
    }

public List<List<Integer>> fourSum(int[] num, int target) {
        int N = num.length;
        List<List<Integer>> res = new ArrayList<List<Integer>>();
        if (N < 4) return res;
        Arrays.sort(num);
        for (int i = 0; i < N; ++i)
        {
            if (i > 0 && num[i] == num[i-1]) continue; for (int j = i+1; j < N; ++j)
            {
                if (j > i+1 && num[j] == num[j-1]) continue; int twosum = target - num[i] - num[j];
                int l = j + 1, r = N - 1;
                while (l < r)
                {
                    int sum = num[l] + num[r];
                    if (sum == twosum) {
                    ArrayList<Integer> tmp = new ArrayList<Integer>();
                    tmp.add(num[i]); tmp.add(num[j]); tmp.add(num[l]); tmp.add(num[r]);
                    res.add(tmp);
                        while (l < r && num[l+1] == num[l]) l++; while (l < r && num[r-1] == num[r]) r--; l++; r--;
                    }
                    else if (sum < twosum) l++;
                    else r--;
                }
            }
        }
        return res;
    }

